add("ru","A2","Deyimler","Мне нужно тебе кое-что сказать","sana bir şey söylemem gerekiyor","ifade","Подожди, мне нужно сказать тебе кое-что важное.","Bekle, sana önemli bir şey söylemem gerekiyor.");
add("ru","A2","Deyimler","Я так взволнован","çok heyecanlıyım","ifade","Честно, я так взволнован насчёт завтра.","Dürüst olmak gerekirse, yarın için çok heyecanlıyım.");
add("ru","A2","Deyimler","Я едва могу усидеть на месте","yerimde duramıyorum","ifade","Честно, я едва могу усидеть на месте от волнения.","Dürüst olmak gerekirse, heyecandan yerimde duramıyorum.");
add("ru","A2","Deyimler","Моё сердце бьётся быстро","kalbim hızlı atıyor","ifade","Честно, моё сердце сейчас бьётся очень быстро.","Dürüst olmak gerekirse, kalbim şu an çok hızlı atıyor.");
add("ru","A2","Deyimler","У меня мурашки от волнения","içimde kelebekler uçuşuyor","ifade","Честно, сейчас у меня мурашки от волнения.","Dürüst olmak gerekirse, şu an içimde kelebekler uçuşuyor.");
add("ru","A2","Deyimler","Мне становится нехорошо от этой мысли","bu düşünceyle fenalaşıyorum","ifade","Честно, мне становится нехорошо от этой мысли.","Dürüst olmak gerekirse, bu düşünceyle fenalaşıyorum.");
add("ru","A2","Deyimler","У меня по спине пробежал холодок","sırtımdan soğuk terler döküldü","ifade","Честно, у меня по спине пробежал холодок.","Dürüst olmak gerekirse, sırtımdan soğuk terler döküldü.");
add("ru","A2","Deyimler","У меня мурашки по коже","tüylerim diken diken oldu","ifade","Честно, у меня сейчас мурашки по коже.","Dürüst olmak gerekirse, şu an tüylerim diken diken oldu.");
add("ru","A2","Deyimler","Это меня пугает","bu beni korkutuyor","ifade","Честно, этот фильм меня очень пугает.","Dürüst olmak gerekirse, bu film beni gerçekten korkutuyor.");
add("ru","A2","Deyimler","Я ужасно боюсь","çok korkuyorum","ifade","Честно, я ужасно боюсь пауков.","Dürüst olmak gerekirse, örümceklerden çok korkuyorum.");
add("ru","A2","Deyimler","Это меня действительно беспокоит","bu beni gerçekten endişelendiriyor","ifade","Честно, это меня действительно беспокоит.","Dürüst olmak gerekirse, bu beni gerçekten endişelendiriyor.");
add("ru","A2","Deyimler","Я действительно беспокоюсь за тебя","senin için gerçekten endişeleniyorum","ifade","Честно, я действительно беспокоюсь за тебя.","Dürüst olmak gerekirse, senin için gerçekten endişeleniyorum.");
add("ru","A2","Deyimler","Не переживай так сильно","bu kadar endişelenme","ifade","Не переживай так сильно, всё будет хорошо.","Bu kadar endişelenme, her şey iyi olacak.");
add("ru","A2","Deyimler","Это меня действительно раздражает","bu beni gerçekten sinir ediyor","ifade","Честно, это раздражает меня уже весь день.","Dürüst olmak gerekirse, tüm gün beni sinir ediyor.");
add("ru","A2","Deyimler","Это действует мне на нервы","bu sinirimi bozuyor","ifade","Честно, это действительно действует мне на нервы.","Dürüst olmak gerekirse, bu gerçekten sinirimi bozuyor.");
add("ru","A2","Deyimler","Я уже сыт этим по горло","bundan bıktım usandım","ifade","Честно, я постепенно сыт этим по горло.","Dürüst olmak gerekirse, yavaş yavaş bundan bıktım usandım.");
add("ru","A2","Deyimler","Я вне себя","kendimden geçmiş durumdayım","ifade","Честно, я сейчас полностью вне себя.","Dürüst olmak gerekirse, şu an tamamen kendimden geçmiş durumdayım.");
add("ru","A2","Deyimler","Я кипячусь от злости","öfkeden kaynıyorum","ifade","Честно, я сейчас кипячусь от злости.","Dürüst olmak gerekirse, şu an öfkeden kaynıyorum.");
add("ru","A2","Deyimler","Глубоко вдохни","derin nefes al","ifade","Глубоко вдохни, всё будет хорошо.","Derin nefes al, her şey yoluna girecek.");
add("ru","A2","Deyimler","Посчитай до десяти","ona kadar say","ifade","Просто посчитай до десяти и успокойся.","Sadece ona kadar say ve sakinleş.");
add("ru","A2","Deyimler","Выговорись","içini dök","ifade","Просто выговорись, тебе станет легче.","Sadece içini dök, kendini daha iyi hissedersin.");
add("ru","A2","Deyimler","Это приятно было сказать","bunu söylemek iyi geldi","ifade","Честно, это было приятно наконец сказать.","Dürüst olmak gerekirse, sonunda bunu söylemek iyi geldi.");
add("ru","A2","Deyimler","У меня словно камень с души свалился","içim rahatladı","ifade","Честно, сейчас у меня словно камень с души свалился.","Dürüst olmak gerekirse, şu an içim rahatladı.");
add("ru","A2","Deyimler","Наконец я могу вздохнуть спокойно","sonunda rahat bir nefes alabilirim","ifade","Наконец я снова могу вздохнуть по-настоящему спокойно.","Sonunda yakında rahat bir nefes alabilirim.");
add("ru","A2","Deyimler","Слава богу","Allah'a şükür","ifade","Слава богу, ничего не случилось.","Allah'a şükür bir şey olmadı.");
add("ru","A2","Deyimler","К счастью, ничего не случилось","iyi ki bir şey olmadı","ifade","К счастью, ни с кем ничего не случилось.","İyi ki kimseye bir şey olmadı.");
add("ru","A2","Deyimler","Нам повезло в этой неудаче","talihsizlikte şanslıydık","ifade","Честно, нам действительно повезло в этой неудаче.","Dürüst olmak gerekirse, gerçekten talihsizlikte şanslıydık.");
add("ru","A2","Deyimler","Как ты себя при этом чувствуешь?","bu konuda nasıl hissediyorsun?","ifade","Скажи, как ты себя при этом чувствуешь?","Söyle bakalım, bu konuda nasıl hissediyorsun?");
add("ru","A2","Deyimler","Я чувствую себя странно из-за этого","bu konuda garip hissediyorum","ifade","Честно, я чувствую себя немного странно из-за этого.","Dürüst olmak gerekirse, bu konuda biraz garip hissediyorum.");
add("ru","A2","Deyimler","Мне комфортно с этим","bu konuda rahatım","ifade","Честно, мне довольно комфортно с этим.","Dürüst olmak gerekirse, bu konuda oldukça rahatım.");
add("ru","A2","Deyimler","Мне неловко из-за этого","bu konuda rahatsızım","ifade","Честно, мне немного неловко из-за этого.","Dürüst olmak gerekirse, bu konuda biraz rahatsızım.");
add("ru","A2","Deyimler","Это кажется правильным","bu doğru hissettiriyor","ifade","Честно, это просто кажется правильным.","Dürüst olmak gerekirse, bu basitçe doğru hissettiriyor.");
add("ru","A2","Deyimler","Это кажется неправильным","bu yanlış hissettiriyor","ifade","Честно, это как-то кажется неправильным.","Dürüst olmak gerekirse, bu bir şekilde yanlış hissettiriyor.");
add("ru","A2","Deyimler","Что-то здесь не так","burada bir şeyler ters gidiyor","ifade","Честно, здесь что-то не так.","Dürüst olmak gerekirse, burada bir şeyler ters gidiyor.");
add("ru","A2","Deyimler","Я не могу это объяснить","bunu açıklayamıyorum","ifade","Честно, я просто не могу это объяснить.","Dürüst olmak gerekirse, bunu basitçe açıklayamıyorum.");
add("ru","A2","Deyimler","У меня нет объяснения этому","bunun için bir açıklamam yok","ifade","Честно, у меня действительно нет объяснения этому.","Dürüst olmak gerekirse, bunun için gerçekten bir açıklamam yok.");
add("ru","A2","Deyimler","В этом нет логического объяснения","bunun mantıklı bir açıklaması yok","ifade","Честно, в этом нет логического объяснения.","Dürüst olmak gerekirse, bunun mantıklı bir açıklaması yok.");
add("ru","A2","Deyimler","В этом нет смысла для меня","bu benim için bir anlam ifade etmiyor","ifade","Честно, в этом нет смысла для меня.","Dürüst olmak gerekirse, bu benim için bir anlam ifade etmiyor.");
add("ru","A2","Deyimler","Теперь всё обретает смысл","şimdi her şey anlam kazandı","ifade","А, теперь наконец всё обретает смысл!","Ah, şimdi sonunda her şey anlam kazandı!");
add("ru","A2","Deyimler","Теперь я понимаю","şimdi anlıyorum","ifade","А, теперь я наконец понимаю!","Ah, şimdi sonunda anlıyorum!");
add("ru","A2","Deyimler","Я наконец понял","sonunda anladım","ifade","Фух, я наконец понял!","Öf, sonunda anladım!");
