add("ru","A2","Deyimler","Можешь объяснить это проще?","bunu daha basit açıklayabilir misin?","ifade","Пожалуйста, можешь объяснить это мне проще?","Lütfen bunu bana daha basit açıklayabilir misin?");
add("ru","A2","Deyimler","Объясни мне, как ребёнку","bana çocuğa anlatır gibi anlat","ifade","Пожалуйста, объясни мне это, как ребёнку.","Lütfen bana bunu çocuğa anlatır gibi anlat.");
add("ru","A2","Deyimler","Простыми словами","basit bir dille","ifade","Простыми словами, речь идёт о деньгах.","Basit bir dille, konu para.");
add("ru","B1","Deyimler","Где мы остановились?","kaldığımız yer neresiydi?","ifade","Хорошо, где именно мы остановились?","Tamam, tam kaldığımız yer neresiydi?");
