add("ru","B1","Deyimler","Я потерял нить разговора","konuyu kaybettim","ifade","Извини, я только что потерял нить разговора.","Üzgünüm, şu an konuyu kaybettim.");
add("ru","B1","Deyimler","На чём я остановился?","nerede kalmıştım?","ifade","Момент, на чём я только что остановился?","Bir dakika, tam nerede kalmıştım?");
add("ru","B1","Deyimler","А да, точно","ah evet, doğru","ifade","А да, точно, я хотел это сказать.","Ah evet, doğru, bunu söylemek istemiştim.");
add("ru","B1","Deyimler","На чём мы остановились?","tam neredeydik?","ifade","Хорошо, на чём мы остановились в истории?","Tamam, hikayede tam neredeydik?");
add("ru","B1","Deyimler","У меня к тебе вопрос","sana bir sorum var","ifade","Извини, у меня к тебе вопрос.","Affedersin, sana bir sorum var.");
add("ru","B1","Deyimler","Могу я тебя кое о чём спросить?","sana bir şey sorabilir miyim?","ifade","Могу я тебя кое о чём быстро спросить?","Sana kısaca bir şey sorabilir miyim?");
add("ru","B1","Deyimler","Спрашивай меня о чём угодно","bana her şeyi sor","ifade","Без проблем, спрашивай меня о чём угодно.","Sorun değil, bana her şeyi sor.");
add("ru","B1","Deyimler","Это хороший вопрос","bu iyi bir soru","ifade","Хм, это действительно хороший вопрос.","Hmm, bu gerçekten iyi bir soru.");
add("ru","B1","Deyimler","Это сложный вопрос","bu zor bir soru","ifade","Честно, это сложный вопрос.","Dürüst olmak gerekirse, bu zor bir soru.");
add("ru","B1","Deyimler","Мне нужно об этом подумать","bunu düşünmem gerekiyor","ifade","Подожди, мне нужно об этом коротко подумать.","Bekle, bunu kısaca düşünmem gerekiyor.");
add("ru","B1","Deyimler","Дай мне минутку подумать","düşünmem için bana bir dakika ver","ifade","Дай мне, пожалуйста, минутку подумать.","Lütfen düşünmem için bana bir dakika ver.");
add("ru","B1","Deyimler","Мне нужно ещё раз подумать","tekrar düşünmem gerekiyor","ifade","Подожди, мне нужно ещё раз об этом подумать.","Bekle, tekrar düşünmem gerekiyor.");
add("ru","B1","Deyimler","Я передумал","fikrimi değiştirdim","ifade","Честно, я передумал.","Dürüst olmak gerekirse, fikrimi değiştirdim.");
add("ru","B1","Deyimler","Я остаюсь при своём мнении","fikrimde kalıyorum","ifade","Нет, я остаюсь при своём мнении.","Hayır, fikrimde kalıyorum.");
add("ru","B1","Deyimler","В конце дня","sonunda / nihayetinde","ifade","Наконец я хочу поблагодарить.","Son olarak teşekkür etmek istiyorum.");
add("ru","B1","Deyimler","В начале было тяжело","başlangıçta zordu","ifade","В начале мне было действительно тяжело.","Başlangıçta benim için gerçekten zordu.");
add("ru","B1","Deyimler","Со временем становится легче","zamanla kolaylaşır","ifade","Не волнуйся, со временем становится легче.","Merak etme, zamanla kolaylaşır.");
add("ru","B1","Deyimler","Шаг за шагом","adım adım","ifade","Мы делаем это шаг за шагом.","Bunu adım adım yapıyoruz.");
add("ru","B1","Deyimler","С самого начала","en baştan","ifade","Объясни мне это с самого начала.","Bunu bana en baştan anlat.");
add("ru","B1","Deyimler","До самого конца","sona kadar","ifade","Я останусь до самого конца.","Sona kadar kalıyorum.");
add("ru","B1","Deyimler","Раз и навсегда","bir kez ve son olarak","ifade","Давай проясним это раз и навсегда.","Hadi bunu bir kez ve son olarak netleştirelim.");
add("ru","B1","Deyimler","На данный момент","şu anlık / şimdilik","ifade","На данный момент всё в порядке.","Şimdilik her şey yolunda.");
add("ru","B1","Deyimler","Только на короткое время","sadece kısa bir süre için","ifade","Я здесь только на короткое время.","Burada sadece kısa bir süre için bulunuyorum.");
add("ru","B1","Deyimler","Это не займёт много времени","uzun sürmez","ifade","Не волнуйся, это не займёт много времени.","Merak etme, uzun sürmez.");
add("ru","B1","Deyimler","Это тянется вечно","bu sonsuza kadar sürüyor","ifade","Честно, это тянется просто вечно!","Dürüst olmak gerekirse, bu sonsuza kadar sürüyor!");
