add("ru","B1","Deyimler","Ты много значишь для меня","benim için çok önemlisin","ifade","Честно, ты много значишь для меня.","Dürüst olmak gerekirse, benim için çok önemlisin.");
add("ru","B1","Deyimler","Не забывай, что ты важен для меня","önemli olduğunu unutma","ifade","Не забывай, что ты важен для меня.","Benim için önemli olduğunu unutma.");
add("ru","B1","Deyimler","Я не могу жить без тебя","sensiz yaşayamam","ifade","Честно, я не могу жить без тебя.","Dürüst olmak gerekirse, sensiz yaşayamam.");
add("ru","B1","Deyimler","Ты делаешь меня счастливым","beni mutlu ediyorsun","ifade","Честно, ты делаешь меня счастливым каждый день.","Dürüst olmak gerekirse, beni her gün mutlu ediyorsun.");
add("ru","B1","Deyimler","С тобой я чувствую себя в безопасности","seninle güvende hissediyorum","ifade","Честно, с тобой я всегда чувствую себя в безопасности.","Dürüst olmak gerekirse, seninle her zaman güvende hissediyorum.");
add("ru","B1","Deyimler","Я могу рассказать тебе всё","sana her şeyi anlatabilirim","ifade","Честно, я действительно могу рассказать тебе всё.","Dürüst olmak gerekirse, sana gerçekten her şeyi anlatabilirim.");
add("ru","B1","Deyimler","Ты понимаешь меня лучше всех","beni en iyi sen anlıyorsun","ifade","Честно, ты понимаешь меня лучше всех остальных.","Dürüst olmak gerekirse, beni en iyi sen anlıyorsun.");
add("ru","B1","Deyimler","Мы хорошо подходим друг другу","iyi uyumluyuz","ifade","Честно, мы действительно хорошо подходим друг другу.","Dürüst olmak gerekirse, gerçekten iyi uyumluyuz.");
add("ru","B1","Deyimler","Мы хорошая команда","iyi bir ekibiz","ifade","Честно, мы действительно хорошая команда.","Dürüst olmak gerekirse, gerçekten iyi bir ekibiz.");
add("ru","B1","Deyimler","Мы хорошо понимаем друг друга","birbirimizi iyi anlıyoruz","ifade","Честно, мы действительно хорошо понимаем друг друга.","Dürüst olmak gerekirse, gerçekten birbirimizi iyi anlıyoruz.");
add("ru","B1","Deyimler","У нас много общего","çok ortak yönümüz var","ifade","Честно, у нас действительно много общего.","Dürüst olmak gerekirse, gerçekten çok ortak yönümüz var.");
add("ru","B1","Deyimler","Мы очень похожи друг на друга","birbirimize çok benziyoruz","ifade","Честно, во многом мы очень похожи друг на друга.","Dürüst olmak gerekirse, birçok konuda birbirimize çok benziyoruz.");
